/**
 * Forge-Zero model catalogue.
 *
 * Everything in this file exists to answer one question: *given a free API key
 * for model X, what does the prompt have to look like so that X actually
 * finishes the job?* A single-file HTML app generated by Gemini 3 Flash needs a
 * different prompt than the same app generated by Llama 3.1 8B on a 6K-token
 * per-minute Groq key.
 *
 * Therefore each profile carries three kinds of truth:
 *   1. Hard ceilings  — contextWindow, outputCeiling, freeTier rate limits.
 *   2. Capabilities   — what API features the endpoint honours (JSON schema,
 *                       system role, streaming, stop sequences).
 *   3. Behavioural quirks — observed failure modes that change the wording of
 *                       the prompt (see QUIRKS for the controlled vocabulary).
 *
 * Quirks are codes, not prose: the composer branches on them, so adding a new
 * model means filling in a row, not writing new generation logic.
 *
 * Limits here were verified against provider docs and independent measurements
 * in September 2026. Free tiers are the most volatile numbers in this industry;
 * every profile exposes `verifiedAt` and the UI surfaces it so a stale row is
 * visible instead of silently wrong.
 */

export const VERIFIED_AT = '2026-09';

/** Controlled vocabulary of prompt-relevant failure modes. */
export const QUIRKS = {
  preamble: {
    label: 'Narrates before code',
    detail:
      'Prefaces output with "Here is the app…" and postambles with explanations, wasting output budget and breaking copy-paste.',
  },
  truncation: {
    label: 'Stops mid-file',
    detail:
      'Silently ends long generations, often inside a function, and then claims the file is complete.',
  },
  'markdown-creep': {
    label: 'Wraps files in prose fences',
    detail:
      'Emits several ```js fences with commentary between them instead of one raw file, so mechanical reassembly fails.',
  },
  'reasoning-tax': {
    label: 'Charges for thinking',
    detail:
      'Reasoning model: chain-of-thought is billed against the same output ceiling as the code.',
  },
  drift: {
    label: 'Instruction drift',
    detail:
      'Loses track of the rules at the top of a long prompt; contracts must be restated near the end.',
  },
  terse: {
    label: 'Under-delivers',
    detail:
      'Replaces requested behaviour with a stub "for brevity" and calls it done.',
  },
  'over-abstract': {
    label: 'Invents frameworks',
    detail:
      'Sprinkles factories, providers and generic helpers where a plain function was wanted.',
  },
  'hallucinated-api': {
    label: 'Invents library APIs',
    detail:
      'Calls plausible-but-nonexistent methods on CDN libraries and current syntax on older pinned versions.',
  },
  'unicode-wobble': {
    label: 'Mangles non-ASCII',
    detail: 'Corrupts emoji and box-drawing characters inside string literals.',
  },
  'summary-addict': {
    label: 'Summarises instead of emitting',
    detail:
      'Answers "add a delete button" with a description of the change rather than the changed file.',
  },
  'self-consistent': {
    label: 'Good at self-review',
    detail: 'Reliably uses an appended acceptance checklist to catch its own bugs.',
  },
  'fast-cheap': {
    label: 'High free throughput',
    detail: 'Generous tokens-per-day for its class; safe for multi-stage plans.',
  },
};

/** Capability flags gate which prompt *protocols* we are allowed to demand. */
const CAP = (over = {}) => ({
  systemRole: true,
  jsonMode: false,
  jsonSchema: false,
  streaming: true,
  temperature: true,
  topP: true,
  stop: true,
  seed: false,
  tools: false,
  vision: false,
  ...over,
});

