/* ------------------------------------------------------------------ *
 * Lookups
 * ------------------------------------------------------------------ */

/** @type {Map<string, object>} flat model id -> enriched profile */
const MODEL_INDEX = new Map();
/** @type {Map<string, object>} model id -> provider */
const MODEL_PROVIDER = new Map();

for (const provider of PROVIDERS) {
  for (const model of provider.models) {
    MODEL_INDEX.set(model.id, {
      ...model,
      provider: provider.id,
      providerLabel: provider.label,
      family: provider.family,
      baseUrl: provider.baseUrl,
      keyUrl: provider.keyUrl,
      docsUrl: provider.docsUrl,
      tierNote: provider.tierNote,
      supports: model.supports ?? CAP({}),
      quirks: model.quirks ?? [],
    });
    MODEL_PROVIDER.set(model.id, provider);
  }
}

export const DEFAULT_MODEL_ID = 'gemini-2.5-flash';

export function listModels() {
  return [...MODEL_INDEX.values()];
}

export function getProviderFor(modelId) {
  return MODEL_PROVIDER.get(modelId) ?? null;
}

/**
 * Fetch a profile, tolerating user-entered ids (e.g. a brand new OpenRouter
 * `:free` slug). Unknown models inherit the conservative limits of the smallest
 * known model from the same provider, because guessing that a model can emit
 * 32K tokens is exactly the mistake that truncates a build at 2am.
 */
export function getModel(modelId, { provider = null } = {}) {
  if (!modelId) return MODEL_INDEX.get(DEFAULT_MODEL_ID);
  const known = MODEL_INDEX.get(modelId);
  if (known) return known;

  const siblings = PROVIDERS.find((p) => p.id === provider)?.models ?? [];
  const fallback = siblings.length
    ? siblings.reduce((a, b) => (a.outputCeiling < b.outputCeiling ? a : b))
    : MODEL_INDEX.get(DEFAULT_MODEL_ID);

  return {
    ...fallback,
    id: modelId,
    label: `${modelId} (unverified)`,
    provider: provider ?? fallback.provider,
    family: PROVIDERS.find((p) => p.id === provider)?.family ?? fallback.family,
    baseUrl: PROVIDERS.find((p) => p.id === provider)?.baseUrl ?? fallback.baseUrl,
    unverified: true,
    quirks: [...new Set([...fallback.quirks, 'drift', 'truncation'])],
    supports: fallback.supports,
    freeTier: fallback.freeTier,
    contextWindow: Math.min(fallback.contextWindow, 128_000),
    outputCeiling: Math.min(fallback.outputCeiling, 8_192),
  };
}

export function modelOptions() {
  return PROVIDERS.map((p) => ({
    provider: p.id,
    label: p.label,
    tierNote: p.tierNote,
    keyUrl: p.keyUrl,
    models: p.models.map((m) => ({
      id: m.id,
      label: m.label,
      contextWindow: m.contextWindow,
      outputCeiling: m.outputCeiling,
      quality: m.quality,
      speedTps: m.speedTps,
      freeTier: m.freeTier,
      quirks: m.quirks,
      bestFor: m.bestFor,
      verifiedAt: m.verifiedAt,
    })),
  }));
}

/* ------------------------------------------------------------------ *
 * Selection
 * ------------------------------------------------------------------ */

const TIER_RANK = { 'unlimited': 3, 'full-stack': 2, 'single-file': 2, 'tiny-apps': 1, 'scaffold-only': 0 };

/**
 * Score the catalogue against a brief and return ranked candidates.
 *
 * The scoring is deliberately opinionated about free-tier reality:
 *  - a model whose outputCeiling cannot hold one stage of the requested size is
 *    penalised hard, because every extra stage costs a rate-limited request;
 *  - a model whose daily request budget is below the number of requests the
 *    plan needs is penalised even if it is smarter;
 *  - tokens-per-minute sets the wall-clock floor for the whole pack, so very
 *    tight TPM models (Groq free tier) are fine for 8K jobs but not 40K ones.
 *
 * @param {object} params
 * @param {'single-file'|'full-stack'} params.mode
 * @param {number} params.targetOutputTokens  total code the plan must emit
 * @param {number} params.requestsNeeded
 * @param {number} params.inputTokensPerRequest
 */
export function recommendModels({
  mode = 'single-file',
  targetOutputTokens = 6_000,
  requestsNeeded = 3,
  inputTokensPerRequest = 2_000,
} = {}) {
  const perStageOutput = Math.max(1, Math.ceil(targetOutputTokens / Math.max(1, requestsNeeded)));
  const scored = listModels().map((m) => {
    const ft = m.freeTier ?? {};
    const reasons = [];
    let score = m.quality * 8;

    // Output ceiling vs the size of one stage.
    const headroom = m.outputCeiling / perStageOutput;
    if (headroom >= 2) score += 26;
    else if (headroom >= 1.15) score += 12;
    else if (headroom >= 0.9) score -= 6;
    else score -= 45;
    reasons.push(`stage ${perStageOutput}t vs ceiling ${m.outputCeiling}t`);

    // Context must hold system + brief + prior files for the later stages.
    const contextNeed = inputTokensPerRequest + targetOutputTokens;
    if (m.contextWindow < contextNeed * 1.3) {
      score -= 22;
      reasons.push('tight context');
    } else if (m.contextWindow > contextNeed * 6) {
      score += 8;
      reasons.push('roomy context');
    }

    // Daily request budget.
    if (ft.rpd != null) {
      const pct = (requestsNeeded / ft.rpd) * 100;
      if (pct > 60) score -= 30;
      else if (pct > 25) score -= 8;
      else score += 10;
      reasons.push(`${pct.toFixed(0)}% of ${ft.rpd} RPD`);
    } else {
      score += 14;
      reasons.push('no daily request cap');
    }

    // Daily token budget.
    const dayTokens = (targetOutputTokens + inputTokensPerRequest) * requestsNeeded;
    if (ft.tpd != null) {
      const pct = (dayTokens / ft.tpd) * 100;
      if (pct > 100) {
        score -= 34;
        reasons.push(`exceeds ${ft.tpd}t/day`);
      } else if (pct > 40) score -= 10;
      else score += 8;
    }

    // Wall-clock: TPM decides how long the pack takes even with no errors.
    if (ft.tpm) {
      const minutes = dayTokens / ft.tpm;
      if (minutes > 12) score -= 18;
      else if (minutes > 4) score -= 6;
      else score += 8;
      reasons.push(`~${minutes.toFixed(1)} min of TPM`);
    }

    // Quirk penalties, scaled by how much the plan depends on long output.
    const q = new Set(m.quirks);
    if (q.has('truncation')) score -= mode === 'full-stack' ? 12 : 6;
    if (q.has('terse')) score -= 8;
    if (q.has('hallucinated-api')) score -= 7;
    if (q.has('reasoning-tax')) score -= 4;
    if (q.has('self-consistent')) score += 6;
    if (q.has('fast-cheap')) score += 8;
    if (q.has('drift') && m.outputCeiling > 12_000) score -= 4;

    // Match the model's declared sweet spot.
    const want = mode === 'full-stack' ? 'full-stack' : 'single-file';
    if (m.bestFor?.includes(want)) score += 14;
    if (m.bestFor?.includes('scaffold-only') && mode === 'full-stack') score -= 12;

    // Privacy: free tiers that train on prompts get flagged, not punished.
    const privacy = ft.trainsOnData ? 'trains-on-data' : 'private';
    if (ft.trainsOnData) score -= 3;

    return {
      modelId: m.id,
      label: m.label,
      provider: m.provider,
      providerLabel: m.providerLabel,
      score: Math.round(score),
      headroom: Number(headroom.toFixed(2)),
      fit: headroom >= 1.15 ? 'comfortable' : headroom >= 0.9 ? 'tight' : 'needs-split',
      privacy,
      verifiedAt: m.verifiedAt,
      reasons,
      quirks: m.quirks,
      freeTier: ft,
      outputCeiling: m.outputCeiling,
      contextWindow: m.contextWindow,
      speedTps: m.speedTps,
      keyUrl: m.keyUrl,
    };
  });

  return scored.sort((a, b) => b.score - a.score);
}

/** Pick the best model id for a brief. */
export function recommendModel(params) {
  const ranked = recommendModels(params);
  return ranked[0]?.modelId ?? DEFAULT_MODEL_ID;
}

/**
 * Fallback chain for a brief: same-ish models on *different* providers, so a
 * 429 or a saturated endpoint does not stall the whole build.
 */
export function fallbackChain(primaryId, params, limit = 3) {
  const primary = MODEL_INDEX.get(primaryId);
  const ranked = recommendModels(params).filter(
    (r) => r.modelId !== primaryId && r.provider !== primary?.provider && r.fit !== 'needs-split'
  );
  return ranked.slice(0, limit).map((r) => r.modelId);
}

export const catalogMeta = () => ({
  verifiedAt: VERIFIED_AT,
  providerCount: PROVIDERS.length,
  modelCount: MODEL_INDEX.size,
  providers: PROVIDERS.map((p) => ({
    id: p.id,
    label: p.label,
    family: p.family,
    baseUrl: p.baseUrl,
    keyUrl: p.keyUrl,
    authHeader: p.authHeader,
    tierNote: p.tierNote,
    modelCount: p.models.length,
  })),
});
